import type { Entry, Project } from './types.js'

// Seconds per project are rounded once to whole minutes, then priced half away from zero.
export function price(entries: Entry[], project: Project): { minutes: number; netMinor: number } {
  const seconds = entries.filter((e) => e.projectId === project.id).reduce((s, e) => s + e.seconds, 0)
  const minutes = Math.round(seconds / 60)
  const netMinor = Math.round((minutes * project.rateMinorPerHour) / 60)
  return { minutes, netMinor }
}

files.src/domain/invoice.ts:
import { price } from './price.js'
import type { Entry, Project } from './types.js'

export function buildInvoice(entries: Entry[], projects: Project[]) {
  const lines = projects.map((p) => ({ project: p.label, ...price(entries, p) })).filter((l) => l.minutes > 0)
  const netMinor = lines.reduce((s, l) => s + l.netMinor, 0)
  return { lines, netMinor, vatMinor: Math.round(netMinor * 0.19) }
}

