import { expect, test } from 'vitest'
import { buildInvoice } from './invoice.js'

test('80 minutes at 64,13 EUR per hour is 85,51 EUR', () => {
  const p = { id: 'p1', label: 'Website relaunch', code: 'web', rateMinorPerHour: 6413 }
  const inv = buildInvoice([{ id: 'e1', projectId: 'p1', startedAt: '2026-10-05T08:00:00Z', seconds: 4800 }], [p])
  expect(inv.netMinor).toBe(8551)
})

